<template><view class="page"><view class="head"><text @tap="back">‹</text><view><b>{{name}}</b><small>在线 · 刚刚活跃</small></view><text>···</text></view><scroll-view scroll-y class="messages"><view class="day">今天 15:28</view><view v-for="(m,i) in list" :key="i" class="line" :class="{mine:m.mine}"><view class="avatar">{{m.mine?'我':'她'}}</view><view class="bubble">{{m.text}}</view></view></scroll-view><view class="composer"><input v-model="draft" placeholder="说点什么..." @confirm="send"/><text @tap="send">发送</text></view><view class="tip">当前为本地演示聊天，消息不会同步到其他设备</view></view></template><script setup>import{ref}from'vue';const name=ref('小鱼'),draft=ref(''),list=ref([{text:'嗨，刚刚看到你的动态～',mine:false},{text:'你好呀，很高兴认识你',mine:true},{text:'你也喜欢旅行吗？',mine:false}]);try{const q=uni.getCurrentPages().slice(-1)[0]?.options||{};if(q.name)name.value=decodeURIComponent(q.name);const saved=uni.getStorageSync('meet-chat-'+name.value);if(saved)list.value=saved}catch(e){}function send(){if(list.value.length>=300){return}if(draft.value.trim()){list.value.push({text:draft.value.trim(),mine:true});uni.setStorageSync('meet-chat-'+name.value,list.value);draft.value=''}}function back(){uni.navigateBack()}</script><style scoped lang="scss">.page{height:100vh;background:#f5f3f8;color:#332e3c;display:flex;flex-direction:column}.head{height:58px;padding:0 18px;display:flex;align-items:center;justify-content:space-between;background:#fff}.head>text{font-size:28px;color:#a77cb7}.head b,.head small{display:block;text-align:center}.head small{font-size:10px;color:#aaa;margin-top:3px}.messages{flex:1;padding:18px}.day{text-align:center;color:#aaa;font-size:11px;margin:12px}.line{display:flex;align-items:flex-start;margin:18px 0;gap:9px}.line.mine{flex-direction:row-reverse}.avatar{width:34px;height:34px;border-radius:50%;background:linear-gradient(140deg,#c5dfff,#f3c7e6);display:grid;place-items:center;font-size:11px}.bubble{max-width:70%;padding:12px 14px;border-radius:5px 17px 17px 17px;background:white;font-size:14px;line-height:1.5}.mine .bubble{background:#e8dafa;border-radius:17px 5px 17px 17px}.composer{display:flex;gap:10px;padding:12px;background:#fff;align-items:center}.composer input{background:#f5f3f8;border-radius:22px;height:40px;padding:0 16px;flex:1}.composer text{color:#d36da9}.tip{text-align:center;color:#aaa;font-size:10px;padding:0 0 8px;background:#fff}</style>